package com.sabyeguyz.clinic.catalog;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/courses") public class CourseManagementController { private final CourseRepository repository; public CourseManagementController(CourseRepository repository){this.repository=repository;} public record Request(@NotBlank @Size(max=40) String code,@NotBlank @Size(max=160) String name,@NotNull @DecimalMin("0.0") BigDecimal price,@Min(1) int sessions,@Min(0) int bonusSessions,@Min(1) int validityDays){} public record Response(Long id,String code,String name,BigDecimal price,int sessions,int bonusSessions,int validityDays,boolean active){} @GetMapping List<Response> list(){return repository.findAllByOrderByName().stream().map(CourseManagementController::response).toList();} @GetMapping("/{id}") Response get(@PathVariable Long id){return response(find(id));} @PostMapping @ResponseStatus(HttpStatus.CREATED) Response create(@Valid @RequestBody Request r){String code=normalize(r.code());if(repository.findByCode(code).isPresent())throw new IllegalArgumentException("รหัส Course ซ้ำ");return response(repository.save(new Course(code,r.name().trim(),r.price(),r.sessions(),r.bonusSessions(),r.validityDays())));} @PutMapping("/{id}") Response update(@PathVariable Long id,@Valid @RequestBody Request r){Course c=find(id);String code=normalize(r.code());if(repository.findByCode(code).filter(found->!found.getId().equals(id)).isPresent())throw new IllegalArgumentException("รหัส Course ซ้ำ");c.update(code,r.name().trim(),r.price(),r.sessions(),r.bonusSessions(),r.validityDays());return response(repository.save(c));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void deactivate(@PathVariable Long id){Course c=find(id);c.deactivate();repository.save(c);} private Course find(Long id){return repository.findById(id).orElseThrow(CourseNotFoundException::new);} private static String normalize(String value){return value.trim().toUpperCase();} private static Response response(Course c){return new Response(c.getId(),c.getCode(),c.getName(),c.getPrice(),c.getSessions(),c.getBonusSessions(),c.getValidityDays(),c.isActive());} }
